<?php
require_once __DIR__ . '/includes/bootstrap.php';
adminRequireLogin(); ensureMisTables(); $conn = adminDb();
if (adminVerifyPost() && isset($_POST['moderate_feedback'])) {
    $id = (int)($_POST['feedback_id'] ?? 0); $decision = $_POST['decision'] ?? '';
    if ($id && in_array($decision, array('approved','rejected'), true)) { $stmt = mysqli_prepare($conn, 'UPDATE delivery_feedback SET status=? WHERE feedback_id=?'); mysqli_stmt_bind_param($stmt, 'si', $decision, $id); mysqli_stmt_execute($stmt); }
    adminRedirect('feedback.php', 'Feedback review saved.');
}
$feedback = adminRows('SELECT f.*,o.name FROM delivery_feedback f LEFT JOIN orders o ON o.orderid=f.orderid ORDER BY FIELD(f.status,\'pending\',\'approved\',\'rejected\'),f.created_at DESC');
$adminTitle = 'Customer feedback'; $adminPage = 'feedback'; include __DIR__ . '/includes/header.php';
?>
<section class="admin-card"><div class="admin-toolbar"><div><h2>Delivery feedback and testimonials</h2><p class="admin-muted">Approve only genuine, positive reviews with testimonial consent. Rejected reviews remain private for service improvement.</p></div></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Order / customer</th><th>Ratings</th><th>Customer comment</th><th>Consent</th><th>Status</th><th>Review</th></tr></thead><tbody><?php foreach($feedback as $item){ ?><tr><td><strong>#<?php echo (int)$item['orderid']; ?></strong><br><span class="admin-muted"><?php echo adminEscape($item['name'] ?: $item['customer_email']); ?></span></td><td>Food: <?php echo (int)$item['food_rating']; ?>/5<br>Service: <?php echo (int)$item['service_rating']; ?>/5<br>Ordering: <?php echo (int)$item['ordering_rating']; ?>/5</td><td><?php echo nl2br(adminEscape($item['comment'] ?: 'No written comment.')); ?></td><td><?php echo $item['consent_to_feature'] ? 'May feature' : 'Internal only'; ?></td><td><span class="admin-badge <?php echo $item['status']==='approved' ? 'live' : ''; ?>"><?php echo adminEscape(ucfirst($item['status'])); ?></span></td><td><?php if($item['status']==='pending'){ ?><form method="post" class="admin-actions"><input type="hidden" name="csrf" value="<?php echo adminEscape(adminToken()); ?>"><input type="hidden" name="feedback_id" value="<?php echo (int)$item['feedback_id']; ?>"><input type="hidden" name="decision" value=""><button class="admin-btn" name="moderate_feedback" value="1" onclick="this.form.decision.value='approved'">Approve</button><button class="admin-btn danger" name="moderate_feedback" value="1" onclick="this.form.decision.value='rejected'">Reject</button></form><?php } else { ?>Reviewed<?php } ?></td></tr><?php } ?></tbody></table><?php if(!$feedback){ ?><p class="admin-muted">No delivery feedback yet.</p><?php } ?></div></section>
<?php include __DIR__ . '/includes/footer.php'; ?>
